#!/usr/bin/env node
/**
 * "Dumb" Stop hook — GUARANTEES a review, does NOT perform it itself.
 *
 * No token, no network, no SDK: it just reads the local git diff and the
 * project's composed rules file (.claude/coding-rules.md, generated by the
 * resolver), then returns a decision in the format expected by Claude Code on
 * stdout. The plugin itself ships NO rules — they come from the consumer project.
 *
 * Two things keep this from over-firing, both driven by a content-aware
 * fingerprint of the working tree stored in `.git/` between invocations:
 *
 *  - Anti-repeat: `git diff HEAD` is cumulative until commit, so a turn that
 *    changes NOTHING (e.g. the user just asked a question) still shows earlier
 *    uncommitted changes. If the fingerprint equals the last settled review, we
 *    let Claude finish instead of re-reviewing.
 *
 *  - Review-until-stable: when a review pass edits code, those edits are
 *    themselves re-reviewed. We keep forcing a pass as long as the fingerprint
 *    keeps changing, and stop once a pass changes nothing (converged) — capped
 *    at MAX_PASSES so a non-converging review can't loop forever.
 *
 * `stop_hook_active` (set by Claude Code inside a Stop-triggered continuation)
 * is what tells a review pass apart from a fresh user turn.
 *
 * Output contract:
 *   { "decision": "block", "reason": "<...>" }  => Claude continues (re-reads/fixes)
 *   {}                                            => Claude can finish
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { execSync } from "node:child_process";
import { createHash } from "node:crypto";

// COMPOSED rules file, generated by the resolver and committed in the repo.
// Same artifact as the one imported by the project's CLAUDE.md → zero drift.
const COMPOSED_RULES = join(process.cwd(), ".claude", "coding-rules.md");

// The composed rules file itself isn't "work to review" — regenerating it
// shouldn't trigger a review pass on its own.
const SELF = [".claude/coding-rules.md"];

// Upper bound on consecutive review passes within a single task. A review pass
// that edits code gets re-reviewed; we stop once a pass changes nothing, or
// after this many passes if the review never converges (safety against loops).
const MAX_PASSES = 3;

function allow() {
  process.stdout.write(JSON.stringify({}));
  process.exit(0);
}

function block(reason) {
  process.stdout.write(JSON.stringify({ decision: "block", reason }));
  process.exit(0);
}

async function readStdin() {
  try {
    const chunks = [];
    for await (const c of process.stdin) chunks.push(c);
    return Buffer.concat(chunks).toString("utf8");
  } catch {
    return "";
  }
}

function changedFiles() {
  let out = "";
  try {
    // Modified tracked files + untracked (new) files.
    // `--exclude-standard` makes git honor .gitignore/.git/info/exclude, so
    // ignored files (build output, deps, generated artifacts…) never appear.
    // No language/extension assumptions: the project's rules decide relevance.
    out = execSync("git diff --name-only HEAD; git ls-files --others --exclude-standard", {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    });
  } catch {
    return []; // not a git repo / no history → don't block
  }
  const seen = new Set();
  return out
    .split("\n")
    .map((f) => f.trim())
    .filter((f) => f && !SELF.includes(f))
    .filter((f) => (seen.has(f) ? false : (seen.add(f), true)));
}

function rulesPresent() {
  return existsSync(COMPOSED_RULES);
}

function git(cmd) {
  return execSync(cmd, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "ignore"],
    maxBuffer: 64 * 1024 * 1024,
  });
}

// Path of the per-repo state file that holds the last-reviewed fingerprint.
// Lives inside .git/ → never tracked, never committed, auto-scoped to the repo.
// Returns null when we're not in a git repo (then fingerprinting is skipped).
function stateFile() {
  try {
    return join(git("git rev-parse --git-dir").trim(), "coding-standards-stop.fingerprint");
  } catch {
    return null;
  }
}

// Content-aware snapshot of the working tree vs HEAD: the tracked-changes patch
// (sensitive to content, not just file names) plus each untracked file's name
// and content. Two turns with an identical tree yield the same hash, which is
// how we tell "nothing changed this turn" apart from "changed earlier, still
// uncommitted".
function fingerprint() {
  const h = createHash("sha256");
  try {
    // Exclude the composed rules file: regenerating it isn't reviewable work.
    h.update(git("git diff HEAD -- ':!.claude/coding-rules.md'"));
  } catch {
    // No HEAD yet (empty repo) → tracked diff contributes nothing; untracked
    // files below still count.
  }
  let others = "";
  try {
    others = git("git ls-files --others --exclude-standard");
  } catch {}
  for (const f of others.split("\n").map((x) => x.trim()).filter(Boolean)) {
    if (SELF.includes(f)) continue;
    h.update("\0U:" + f + "\0");
    try {
      h.update(readFileSync(f));
    } catch {}
  }
  return h.digest("hex");
}

// State = { fp, passes }:
//   passes === 0  → fp is a settled/accepted baseline (last review converged).
//   passes >= 1   → we're in a review chain; fp is the state last sent for
//                   review, passes is how many review passes have run so far.
function readState(path) {
  if (!path || !existsSync(path)) return null;
  try {
    const s = JSON.parse(readFileSync(path, "utf8"));
    if (s && typeof s.fp === "string" && Number.isInteger(s.passes)) return s;
  } catch {}
  return null;
}

function writeState(path, fp, passes) {
  if (!path || fp === null) return;
  try {
    writeFileSync(path, JSON.stringify({ fp, passes }));
  } catch {}
}

function buildReason(files, hasRules) {
  const head = [
    "⏸️ Mandatory review before finishing (Stop hook).",
    "",
    "You modified these files:",
    ...files.map((f) => `- ${f}`),
    "",
  ];

  // The composed rules are already in context (imported by CLAUDE.md), so we
  // point to the file instead of pasting its whole content into this message.
  if (!hasRules) {
    return [
      ...head,
      "The composed rules file `.claude/coding-rules.md` is missing — run",
      "`/update-coding-rules` to generate it, then review the files above.",
    ].join("\n");
  }

  return [
    ...head,
    "Re-read the composed rules in `.claude/coding-rules.md` and check the files",
    "above against them. Fix every violation of severity **major** or **critical**;",
    "report the **minor** / **info** ones (ignore WARN-ONLY modules as blocking).",
    "Once fixed, finish normally (this hook will not ask you again).",
  ].join("\n");
}

async function main() {
  const rawInput = await readStdin();
  let input = {};
  try {
    input = rawInput ? JSON.parse(rawInput) : {};
  } catch {
    input = {};
  }

  const state = stateFile();
  const fp = state ? fingerprint() : null;
  const files = changedFiles();

  // A) Nothing modified vs HEAD → nothing to review; record a settled baseline.
  if (files.length === 0) {
    writeState(state, fp, 0);
    return allow();
  }

  const prev = readState(state);

  if (input.stop_hook_active === true) {
    // We're inside the review chain we forced earlier.
    if (fp !== null && prev && prev.fp === fp) {
      // The review pass changed nothing → converged → accept as baseline.
      writeState(state, fp, 0);
      return allow();
    }
    // The review edited code → re-verify those edits, but cap the number of
    // passes so a review that never converges can't loop forever.
    const passes = prev ? prev.passes : 1;
    if (passes >= MAX_PASSES) {
      writeState(state, fp, 0);
      return allow();
    }
    writeState(state, fp, passes + 1);
    return block(buildReason(files, rulesPresent()));
  }

  // Fresh user turn (not a review continuation).
  // B) Unchanged since the last settled review → don't re-trigger (e.g. the user
  //    just asked a question; the earlier diff is still uncommitted).
  if (fp !== null && prev && prev.passes === 0 && prev.fp === fp) {
    return allow();
  }

  // C) New / unreviewed work → start a review chain.
  writeState(state, fp, 1);
  return block(buildReason(files, rulesPresent()));
}

main().catch(() => allow()); // on error, never block the dev
